-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 notable NPCs are in' AS assertion, count(*) AS got, 3 AS want
  FROM notable_npcs WHERE slug IN ('overlord-sindel', 'overlord-sthena', 'queen-marauder');
SELECT 'and the notables 23' AS assertion, count(*) AS got, 23 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('overlord-sindel', 'overlord-sthena', 'queen-marauder');

